from pathlib import Path
import hashlib, re, shutil

SOURCE = Path("client/queuepop_companion.py")
EXPECTED_BEFORE = "082b78f4d2d1a1ca56a70ac5959d804f604a905d1fefb4482effda6d63ca7de1"
EXPECTED_AFTER = "78b7735c07ad96ac7bb6bd5a2b20cb36eb00c05951c119cc041e4b355cbd70df"
ICONS = {
    "PUSHOVER": "",
    "NTFY": "",
    "TELEGRAM": "",
}

data = SOURCE.read_bytes()
actual = hashlib.sha256(data).hexdigest()
if actual != EXPECTED_BEFORE:
    raise RuntimeError(f"Unexpected source before release patch: {actual}")
text = data.decode("utf-8")
for key, value in ICONS.items():
    pattern = rf'{key}_SERVICE_ICON_B64 = """.*?"""'
    replacement = f'{key}_SERVICE_ICON_B64 = """{value}"""'
    text, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError(f"Could not patch {key} icon")
SOURCE.write_text(text, encoding="utf-8")
after = hashlib.sha256(SOURCE.read_bytes()).hexdigest()
if after != EXPECTED_AFTER:
    raise RuntimeError(f"Final source checksum mismatch: {after}")
shutil.rmtree(".release_source", ignore_errors=True)
print(f"Verified release source: {after}")
